1:import { type Api, start } from './api.js';
2:import * as autoPieces from './autoPieces.js';
3:import { type Config, configure } from './config.js';
4:import * as events from './events.js';
5:import { render, renderResized, updateBounds } from './render.js';
6:import { defaults, type HeadlessState, type State } from './state.js';
7:import * as svg from './svg.js';
8:import * as util from './util.js';
9:import { renderWrap } from './wrap.js';
10:
11:export function initModule({ el, config }: { el: HTMLElement; config?: Config }): Api {
12:  return Chessground(el, config);
13:}
14:
15:export function Chessground(element: HTMLElement, config?: Config): Api {
16:  const maybeState: State | HeadlessState = defaults();
17:
18:  configure(maybeState, config || {});
19:
20:  function redrawAll(): State {
21:    const prevUnbind = 'dom' in maybeState ? maybeState.dom.unbind : undefined;
22:    // compute bounds from existing board element if possible
23:    // this allows non-square boards from CSS to be handled (for 3D)
24:    const elements = renderWrap(element, maybeState),
25:      bounds = util.memo(() => elements.board.getBoundingClientRect()),
26:      redrawNow = (skipSvg?: boolean): void => {
27:        render(state);
28:        if (elements.autoPieces) autoPieces.render(state, elements.autoPieces);
29:        if (!skipSvg && elements.shapes) svg.renderSvg(state, elements);
30:      },
31:      onResize = (): void => {
32:        updateBounds(state);
33:        renderResized(state);
34:        if (elements.autoPieces) autoPieces.renderResized(state);
35:      };
36:    const state = maybeState as State;
37:    state.dom = {
38:      elements,
39:      bounds,
40:      redraw: debounceRedraw(redrawNow),
41:      redrawNow,
42:      unbind: prevUnbind,
43:    };
44:    state.drawable.prevSvgHash = '';
45:    updateBounds(state);
46:    redrawNow(false);
47:    events.bindBoard(state, onResize);
48:    if (!prevUnbind) state.dom.unbind = events.bindDocument(state, onResize);
49:    state.events.insert?.(elements);
50:    return state;
51:  }
52:
53:  return start(redrawAll(), redrawAll);
54:}
55:
56:function debounceRedraw(redrawNow: (skipSvg?: boolean) => void): () => void {
57:  let redrawing = false;
58:  return () => {
59:    if (redrawing) return;
60:    redrawing = true;
61:    requestAnimationFrame(() => {
62:      redrawNow();
63:      redrawing = false;
64:    });
